#!/usr/bin/env node
/// <reference types="node" />
/**
 * What is holding the weight? Exports the production JS bundle, then uses its
 * source map to attribute every generated byte to the npm package (or app
 * folder) it came from, and ranks them.
 *
 *   pnpm run perf:bundle                        # android, top 25
 *   pnpm run perf:bundle -- --platform ios --top 40
 *   pnpm run perf:bundle -- --budget            # exit 1 if over perf-budget.json
 *   pnpm run perf:bundle -- --update-budget     # write today's size + 5% headroom
 *   pnpm run perf:bundle -- --skip-export       # re-analyse the last export
 *
 * Sizes are of the minified JS before Hermes bytecode compilation, which is
 * what the source map describes; they are proportional to, not equal to, the
 * bytes inside the APK/IPA. Gzip is shown as a rough download/OTA-update size.
 * Output: dist/bundle-report/<platform>/ (export) and report.json.
 */

import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import zlib from 'node:zlib'
import { alternativeFor, TRANSITIVE_HINTS } from './lib/dependency-alternatives.ts'

type Budget = Record<string, { maxBundleKB: number, maxGzipKB: number }>
type Row = { name: string, bytes: number }

const ROOT = process.cwd()
const argv = process.argv.slice(2)
const flag = (name: string, fallback: string) => {
  const i = argv.indexOf(name)
  return i >= 0 && argv[i + 1] ? argv[i + 1] : fallback
}
const PLATFORM = flag('--platform', 'android')
const TOP = Number(flag('--top', '25'))
const OUT_DIR = path.join(ROOT, 'dist', 'bundle-report', PLATFORM)
const BUDGET_FILE = path.join(ROOT, 'perf-budget.json')
const lines: string[] = []

function out(line = ''): void {
  lines.push(line)
  console.log(line)
}

function fail(message: string): never {
  console.error(`✖ ${message}`)
  process.exit(1)
}

function exportBundle(): void {
  const cli = path.join(ROOT, 'node_modules', 'expo', 'bin', 'cli')
  if (!fs.existsSync(cli))
    fail('node_modules is missing — run `pnpm run install:safe` first.')
  fs.rmSync(OUT_DIR, { recursive: true, force: true })
  console.log(`Exporting the production ${PLATFORM} bundle…`)
  const result = spawnSync(process.execPath, [cli, 'export', '--platform', PLATFORM, '--source-maps', '--no-bytecode', '--output-dir', OUT_DIR], {
    cwd: ROOT,
    stdio: 'inherit',
    env: { ...process.env, NODE_ENV: 'production', EXPO_PUBLIC_APP_ENV: process.env.EXPO_PUBLIC_APP_ENV ?? 'production' },
  })
  if (result.status !== 0)
    fail('`expo export` failed — see the output above.')
}

function findBundle(dir: string): { js: string, map: string } {
  const files: string[] = []
  const walk = (d: string) => {
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      const full = path.join(d, entry.name)
      if (entry.isDirectory())
        walk(full)
      else files.push(full)
    }
  }
  walk(dir)
  const map = files.filter(f => f.endsWith('.map')).sort((a, b) => fs.statSync(b).size - fs.statSync(a).size)[0]
  const js = map?.replace(/\.map$/, '')
  if (!map || !js || !fs.existsSync(js))
    fail(`No bundle + source map found under ${path.relative(ROOT, dir)}. Run without --skip-export.`)
  return { js, map }
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const B64 = new Map([...BASE64].map((c, i) => [c, i]))

/** Decodes one VLQ segment ("AACA") into numbers. */
function decodeSegment(segment: string): number[] {
  const values: number[] = []
  let value = 0
  let shift = 0
  for (const char of segment) {
    const digit = B64.get(char)
    if (digit === undefined)
      break
    value += (digit & 31) << shift
    if (digit & 32) {
      shift += 5
      continue
    }
    values.push(value & 1 ? -(value >>> 1) : value >>> 1)
    value = 0
    shift = 0
  }
  return values
}

type FlatMap = { sources: string[], mappings: string }
type IndexedMap = { sections: Array<{ offset: { line: number, column: number }, map: FlatMap }> }

/**
 * Bytes of generated code per owner. Handles flat maps and the indexed
 * (`sections`) maps Metro emits — one section per module, each offset into
 * the bundle. Every mapping segment becomes a span on the bundle's line/column
 * grid; a span runs until the next span on the same line (from any section)
 * or the end of the line.
 */
function bytesPerOwner(code: string, sourceMap: FlatMap | IndexedMap): Map<string, number> {
  const generatedLines = code.split('\n')
  const sections = 'sections' in sourceMap ? sourceMap.sections : [{ offset: { line: 0, column: 0 }, map: sourceMap }]
  const owners: string[] = []
  const ownerIndex = new Map<string, number>()
  // spansByLine[line] = flat [col, owner, col, owner, …]; owner -1 = unmapped.
  const spansByLine = new Map<number, number[]>()

  for (const { offset, map } of sections) {
    const sourceOwners = map.sources.map((source) => {
      const owner = ownerOf(source)
      if (!ownerIndex.has(owner)) {
        ownerIndex.set(owner, owners.length)
        owners.push(owner)
      }
      return ownerIndex.get(owner) as number
    })
    let source = 0
    map.mappings.split(';').forEach((line, lineIndex) => {
      const generatedLine = offset.line + lineIndex
      let column = lineIndex === 0 ? offset.column : 0
      const spans = spansByLine.get(generatedLine) ?? []
      for (const segment of line.split(',')) {
        if (!segment)
          continue
        const [colDelta, srcDelta] = decodeSegment(segment)
        column += colDelta ?? 0
        if (srcDelta !== undefined)
          source += srcDelta
        spans.push(column, srcDelta !== undefined ? sourceOwners[source] ?? -1 : -1)
      }
      if (spans.length)
        spansByLine.set(generatedLine, spans)
    })
  }

  const totals = Array.from({ length: owners.length }, () => 0)
  for (const [line, flat] of spansByLine) {
    const pairs: Array<[number, number]> = []
    for (let i = 0; i < flat.length; i += 2)
      pairs.push([flat[i], flat[i + 1]])
    pairs.sort((a, b) => a[0] - b[0])
    const lineLength = generatedLines[line]?.length ?? 0
    pairs.forEach(([col, owner], i) => {
      const end = pairs[i + 1]?.[0] ?? lineLength
      if (owner >= 0 && end > col)
        totals[owner] += end - col
    })
  }
  return new Map(owners.map((owner, i) => [owner, totals[i]]))
}

function ownerOf(source: string): string {
  const normalized = source.replace(/\\/g, '/')
  const idx = normalized.lastIndexOf('node_modules/')
  if (idx >= 0) {
    const rest = normalized.slice(idx + 'node_modules/'.length).split('/')
    return rest[0].startsWith('@') ? `${rest[0]}/${rest[1]}` : rest[0]
  }
  const local = normalized.match(/(?:^|\/)(src\/[^/]+|app)\//)
  return local ? `‹${local[1]}›` : '‹other›'
}

function kb(bytes: number): string {
  return `${(bytes / 1024).toFixed(1)} KB`
}

function main(): void {
  if (!argv.includes('--skip-export'))
    exportBundle()
  const { js, map } = findBundle(OUT_DIR)
  const code = fs.readFileSync(js, 'utf8')
  const sourceMap = JSON.parse(fs.readFileSync(map, 'utf8')) as FlatMap | IndexedMap
  const byOwner = bytesPerOwner(code, sourceMap)
  const moduleCount = 'sections' in sourceMap ? sourceMap.sections.length : sourceMap.sources.length
  const rows: Row[] = [...byOwner].map(([name, bytes]) => ({ name, bytes })).sort((a, b) => b.bytes - a.bytes)

  const total = Buffer.byteLength(code)
  const gzip = zlib.gzipSync(code, { level: 9 }).length
  const attributed = rows.reduce((sum, r) => sum + r.bytes, 0)

  out(`# Bundle report — ${PLATFORM}`)
  out(`bundle ${kb(total)} · gzip ${kb(gzip)} · ${moduleCount} modules · ${rows.length} owners · ${((attributed / total) * 100).toFixed(0)}% attributed`)
  out()
  out(`${'#'.padStart(3)}  ${'package / folder'.padEnd(42)} ${'size'.padStart(10)}  share   note`)
  rows.slice(0, TOP).forEach((row, i) => {
    const alt = alternativeFor(row.name)
    const note = alt ? `→ ${alt.instead.split(' — ')[0]}` : TRANSITIVE_HINTS[row.name] ?? ''
    out(`${String(i + 1).padStart(3)}  ${row.name.padEnd(42)} ${kb(row.bytes).padStart(10)}  ${((row.bytes / total) * 100).toFixed(1).padStart(4)}%  ${note}`)
  })
  if (rows.length > TOP)
    out(`     … ${rows.length - TOP} more (--top ${rows.length})`)
  out()
  out('Full alternatives (why, effort, native change): `pnpm run deps:check` · details: docs/PERFORMANCE.md')

  fs.writeFileSync(path.join(OUT_DIR, '..', `report-${PLATFORM}.json`), JSON.stringify({ platform: PLATFORM, bundleBytes: total, gzipBytes: gzip, owners: rows }, null, 2))

  const budget: Budget = fs.existsSync(BUDGET_FILE) ? JSON.parse(fs.readFileSync(BUDGET_FILE, 'utf8')) : {}
  if (argv.includes('--update-budget')) {
    budget[PLATFORM] = { maxBundleKB: Math.ceil((total / 1024) * 1.05), maxGzipKB: Math.ceil((gzip / 1024) * 1.05) }
    fs.writeFileSync(BUDGET_FILE, `${JSON.stringify(budget, null, 2)}\n`)
    out(`\n✔ perf-budget.json: ${PLATFORM} ≤ ${budget[PLATFORM].maxBundleKB} KB (gzip ≤ ${budget[PLATFORM].maxGzipKB} KB)`)
  }
  else if (argv.includes('--budget')) {
    const limit = budget[PLATFORM]
    if (!limit)
      fail(`No ${PLATFORM} entry in perf-budget.json — run with --update-budget once.`)
    const over = [total / 1024 > limit.maxBundleKB && `bundle ${kb(total)} > ${limit.maxBundleKB} KB`, gzip / 1024 > limit.maxGzipKB && `gzip ${kb(gzip)} > ${limit.maxGzipKB} KB`].filter(Boolean)
    if (over.length) {
      out(`\n✖ Over budget: ${over.join(' · ')}. Find the new weight in the table above, or raise the budget deliberately with --update-budget.`)
      process.exitCode = 1
    }
    else {
      out(`\n✔ Within budget (${limit.maxBundleKB} KB / gzip ${limit.maxGzipKB} KB)`)
    }
  }

  if (process.env.GITHUB_STEP_SUMMARY)
    fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `\`\`\`\n${lines.join('\n')}\n\`\`\`\n`)
}

main()
